{"cards": [{"node_code": "N_1c61d42dd9c432a1", "definition": "研究船舶内部用于支撑机械设备、管路及附属设施的基座结构，以及针对局部高应力或特殊工况设计的加强构件与结构形式。", "boundary": "本节点聚焦于“支撑”与“局部加强”功能。边界在于区分“基座”（设备支撑）与“船体骨架”（整体结构）、“特殊加强”（局部补强）与“常规结构”（标准构件）。若内容涉及基座的焊接工艺，归入建造工艺；若涉及基座受力计算，归入船舶原理。", "includes": ["主机、辅机、泵浦等设备的基座设计与构造", "甲板开口、舱口、轴隧等处的局部加强结构", "承受集中载荷或冲击载荷的特殊结构件"], "excludes": ["船体主骨架（如肋骨、纵骨、横梁）的常规构造", "基座与设备的安装、调试及焊接制造工艺", "基座结构的纯力学理论推导"], "sibling_distinctions": [{"other_code": "N_d55f2b57f80e3a49", "rule": "船体侧重整体骨架与外壳，本节点侧重内部设备支撑及局部补强结构。"}, {"other_code": "N_14a3eefd55415168", "rule": "甲板及上层建筑侧重水平与垂直围护结构，本节点侧重其下方的支撑基座及开口处的加强。"}], "cross_boundary_rule": "若内容涉及“基座疲劳分析”，侧重结构构造细节归入本节点；侧重整体寿命评估模型可关联船舶原理。"}, {"node_code": "N_d7558ec7075ef83c", "definition": "研究船舶内部由舱壁、甲板及船壳围成的封闭空间（船舱）的结构构造、分舱形式、水密完整性及内部布置要求。", "boundary": "本节点聚焦于“空间”与“分舱”构造。边界在于区分“船舱”（空间划分）与“舱壁”（分隔构件）、“船体”（整体结构）。若内容涉及舱壁板的厚度与连接，归入舱壁；若涉及舱内设备布置，归入船舶设计或舾装。", "includes": ["船舶分舱原则、水密舱与风雨密舱的构造", "机舱、货舱、住舱等不同功能舱室的结构要求", "舱室开口（门、窗、通风筒）的密封与加强构造"], "excludes": ["舱壁、甲板等具体构件的材料与连接工艺", "舱内设备（如主机、货舱盖）的设计与安装", "船舶总体设计中的舱室容积计算与布置方案"], "sibling_distinctions": [{"other_code": "N_7f0b79f8715c770a", "rule": "舱壁侧重分隔构件本身的构造，船舱侧重由构件围成的空间及其功能属性。"}, {"other_code": "N_14a3eefd55415168", "rule": "甲板及上层建筑侧重水平/垂直围护面，船舱侧重其围合形成的内部空间。"}], "cross_boundary_rule": "若内容涉及“舱室破损进水计算”，侧重空间划分与完整性归入本节点；侧重流体动力学可关联船舶原理。"}, {"node_code": "N_264ffd95e32e7f56", "definition": "研究除传统钢材外，复合材料、铝合金、钛合金、木材等非金属材料在船体结构中的应用构造、连接方式及性能特点。", "boundary": "本节点聚焦于“非传统材料”的结构应用。边界在于区分“材料结构”（应用构造）与“材料科学”（材料本身性能）、“常规钢结构”（其他兄弟节点）。若内容涉及复合材料的制备工艺，归入材料科学或建造工艺；若涉及铝合金船体的常规构造，归入本节点。", "includes": ["玻璃钢（FRP）、碳纤维等复合材料船体的结构构造", "铝合金、镁合金等轻金属船体的结构设计与连接", "木材、竹材等传统或新型非金属材料在船舶结构中的应用"], "excludes": ["钢材船体的常规结构构造（归入船壳、船体等节点）", "非金属材料本身的合成、加工及冶金性能研究", "非金属材料结构的焊接、胶接等具体制造工艺"], "sibling_distinctions": [{"other_code": "N_c26f523d5ec55dae", "rule": "船壳通常指钢质船壳，本节点特指非钢质材料的船壳及结构构造。"}, {"other_code": "N_d55f2b57f80e3a49", "rule": "船体通常指钢质整体结构，本节点特指非钢质材料的整体结构构造。"}], "cross_boundary_rule": "若内容涉及“复合材料结构疲劳”，侧重材料特性归入本节点；侧重结构构造细节归入本节点；侧重纯理论可关联船舶原理。"}]}
